CREATE TABLE "annonces_site" ("id" SERIAL PRIMARY KEY, "texte" TEXT NOT NULL, "actif" BOOLEAN NOT NULL DEFAULT true, "ordre" INTEGER NOT NULL DEFAULT 0, "dureeSecondes" INTEGER NOT NULL DEFAULT 5, "creeLe" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "misAJourLe" TIMESTAMP(3) NOT NULL);
CREATE TABLE "bannieres_site" ("id" SERIAL PRIMARY KEY, "image" TEXT NOT NULL, "titre" TEXT, "description" TEXT, "lien" TEXT, "actif" BOOLEAN NOT NULL DEFAULT true, "ordre" INTEGER NOT NULL DEFAULT 0, "dateDebut" TIMESTAMP(3), "dateFin" TIMESTAMP(3), "creeLe" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "misAJourLe" TIMESTAMP(3) NOT NULL);
